'use client'

import * as React from 'react'

import { useReducedMotion } from './use-reduced-motion'
import './dock.css'

export type DockItem = {
    /** Accessible name, also shown as the tooltip label. */
    label: string
    icon: React.ReactNode
    onSelect?: () => void
}

export type DockProps = {
    items: DockItem[]
    /** Accessible name for the toolbar. */
    label?: string
    /** Extra scale for the item under the pointer. */
    magnification?: number
    className?: string
}

// A toolbar of icon buttons that swell near the pointer. One Tab stop; arrow keys
// move between items (the toolbar pattern), and the focused item magnifies too.
const Dock = ({ items, label = 'Dock', magnification = 0.6, className }: DockProps) => {
    const ref = React.useRef<HTMLDivElement | null>(null)
    const reduced = useReducedMotion(ref)
    const buttons = React.useRef<(HTMLButtonElement | null)[]>([])
    const [active, setActive] = React.useState(0)

    const handleMove = (event: React.PointerEvent<HTMLDivElement>) => {
        if (reduced || event.pointerType === 'touch') return
        buttons.current.forEach((button) => {
            if (!button) return
            const rect = button.getBoundingClientRect()
            const distance = Math.abs(event.clientX - (rect.left + rect.width / 2))
            const influence = Math.max(0, 1 - distance / 140)
            button.style.setProperty('--rad-fx-dock-scale', `${1 + influence * magnification}`)
        })
    }

    const reset = () => buttons.current.forEach((button) => button?.style.setProperty('--rad-fx-dock-scale', '1'))

    const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
        const moves: Record<string, number> = { ArrowRight: 1, ArrowLeft: -1, Home: -Infinity, End: Infinity }
        if (!(event.key in moves)) return
        event.preventDefault()
        const step = moves[event.key]
        const next = step === -Infinity ? 0 : step === Infinity ? items.length - 1 : (active + step + items.length) % items.length
        setActive(next)
        buttons.current[next]?.focus()
    }

    return <div
        ref={ref}
        role="toolbar"
        aria-label={label}
        aria-orientation="horizontal"
        className={['rad-fx-dock', className].filter(Boolean).join(' ')}
        onPointerMove={handleMove}
        onPointerLeave={reset}
        onKeyDown={handleKeyDown}
    >
        {items.map((item, i) => (
            <button
                key={item.label}
                ref={(node) => { buttons.current[i] = node }}
                type="button"
                className="rad-fx-dock-item"
                aria-label={item.label}
                tabIndex={i === active ? 0 : -1}
                onFocus={() => setActive(i)}
                onClick={item.onSelect}
            >
                <span className="rad-fx-dock-icon" aria-hidden="true">{item.icon}</span>
                <span className="rad-fx-dock-tip" aria-hidden="true">{item.label}</span>
            </button>
        ))}
    </div>
}

export default Dock

.rad-fx-dock {
    display: inline-flex;
    align-items: flex-end;
    gap: 10px;
    padding: 10px 12px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 20px;
    background: rgba(24, 24, 32, 0.6);
    backdrop-filter: blur(14px);
}

.rad-fx-dock-item {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 46px;
    height: 46px;
    padding: 0;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    background: linear-gradient(160deg, rgba(255, 255, 255, 0.14), rgba(255, 255, 255, 0.04));
    color: #f4f4f5;
    cursor: pointer;
    transform-origin: 50% 100%;
    transform: scale(var(--rad-fx-dock-scale, 1));
    transition: transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.rad-fx-dock-item:focus-visible {
    --rad-fx-dock-scale: 1.35;
    outline: 2px solid #f4f4f5;
    outline-offset: 3px;
}

.rad-fx-dock-icon { display: inline-flex; }

/* Visual tooltip for sighted users; the accessible name comes from aria-label. */
.rad-fx-dock-tip {
    position: absolute;
    bottom: calc(100% + 10px);
    left: 50%;
    padding: 3px 8px;
    border-radius: 6px;
    background: #f4f4f5;
    color: #0b0b0f;
    font-size: 12px;
    white-space: nowrap;
    pointer-events: none;
    opacity: 0;
    transform: translate(-50%, 4px) scale(calc(1 / var(--rad-fx-dock-scale, 1)));
    transition: opacity 150ms ease, transform 150ms ease;
}

.rad-fx-dock-item:hover .rad-fx-dock-tip,
.rad-fx-dock-item:focus-visible .rad-fx-dock-tip {
    opacity: 1;
    transform: translate(-50%, 0) scale(calc(1 / var(--rad-fx-dock-scale, 1)));
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-dock-item { transition: none; transform: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-dock-item { transition: none; transform: none; }
